lib_src='''def bbox_nonzero(grid, bg=0):
    """The bounding box (top, left, height, width) of all cells that differ from bg."""
    pts = [(i, j) for i, row in enumerate(grid) for j, v in enumerate(row) if v != bg]
    top = min(p[0] for p in pts); left = min(p[1] for p in pts)
    return top, left, max(p[0] for p in pts) - top + 1, max(p[1] for p in pts) - left + 1

def crop(grid, top, left, height, width):
    """The height x width subgrid whose top-left cell is (top, left)."""
    return [row[left:left + width] for row in grid[top:top + height]]

def hflip(grid):
    """The grid mirrored left to right."""
    return [row[::-1] for row in grid]

def rotate_cw(grid):
    """The grid rotated 90 degrees clockwise."""
    return [list(r) for r in zip(*grid[::-1])]

def largest_component_bbox(grid, bg=0):
    """The bounding box of the largest 4-connected component of non-background cells."""
    h, w = len(grid), len(grid[0])
    seen = [[False]*w for _ in range(h)]
    best = None
    for i in range(h):
        for j in range(w):
            if grid[i][j] != bg and not seen[i][j]:
                stack = [(i, j)]; seen[i][j] = True; comp = []
                while stack:
                    r, c = stack.pop(); comp.append((r, c))
                    for dr, dc in ((1,0),(-1,0),(0,1),(0,-1)):
                        nr, nc = r+dr, c+dc
                        if 0 <= nr < h and 0 <= nc < w and not seen[nr][nc] and grid[nr][nc] != bg:
                            seen[nr][nc] = True; stack.append((nr, nc))
                if best is None or len(comp) > len(best):
                    best = comp
    rs = [p[0] for p in best]; cs = [p[1] for p in best]
    return min(rs), min(cs), max(rs)-min(rs)+1, max(cs)-min(cs)+1

def extract_block(grid, bg=0):
    """The smallest subgrid containing the largest connected non-background component."""
    top, left, h, w = largest_component_bbox(grid, bg)
    return crop(grid, top, left, h, w)
